/// Compatibility path for heuristic parsers without an AST; spans stay exact.
pub fn chunk_with_symbols(
    &self,
    file_path: &str,
    content: &str,
    language: Language,
    symbols: &[SymbolRecord],
    parser_tier: ParserTier,
    parser_confidence: f64,
) -> Vec<ChunkRecord> {
    let source = SourceSnapshot::new(content.as_bytes());
    let mut structure = SourceStructure::fallback(&source, "heuristic_symbol_lines");
    let mut items: Vec<_> = symbols
        .iter()
        .filter_map(|s| {
            source
                .line_range(
                    s.start_line as usize,
                    (s.end_line as usize).min(source.line_count()),
                )
                .ok()
                .map(|span| (s, span))
        })
        .collect();
    items.sort_by_key(|(_, s)| (s.start, std::cmp::Reverse(s.end)));
    let mut parents: Vec<usize> = Vec::new();
    for (symbol, span) in items.into_iter().take(50_000) {
        while parents.last().is_some_and(|&i| {
            !structure.boundaries[i].span.contains(span) || structure.boundaries[i].span == span
        }) {
            parents.pop();
        }
        let parent = parents.last().map(|&i| i as u32);
        let i = structure.boundaries.len();
        structure.boundaries.push(SyntaxBoundary {
            span,
            parent,
            kind: BoundaryKind::Symbol,
            name: Some(symbol.name.clone()),
            symbol_kind: Some(symbol.kind),
            signature: None,
            leading_comment: None,
            documentation: None,
        });
        parents.push(i);
    }
    self.from_structure(
        file_path,
        &source,
        language,
        &structure,
        parser_tier,
        parser_confidence,
    )
}

fn layer_scores_sum_to_total() {
    let (_tmp, db) = db_with_symbols();
    let boost = vec!["src/a.rs".to_string()];
    let recent = vec!["src/a.rs".to_string(), "src/b.rs".to_string()];
    let req = PreselectRequest {
        query: "user",
        path_prefix: None,
        boost_paths: Some(&boost),
        recent_paths: Some(&recent),
        pinned_paths: None,
        overlay_paths: None,
        explicit_file_paths: None,
        limit: 10,
        ranking: &RankingConfig::default(),
    };
    let result = preselect(&db, &req).unwrap();
    assert!(!result.files.is_empty());
    for file in &result.files {
        let total = result.scores[file];
        let bill = result
            .layer_scores
            .get(file)
            .unwrap_or_else(|| panic!("missing bill for {}", file));
        let bill_sum: f64 = bill.iter().map(|(_, s)| s).sum();
        assert!(
            (bill_sum - total).abs() < 1e-9,
            "bill for {} must sum to total: {:?} vs {}",
            file,
            bill,
            total
        );
    }
    // src/a.rs got working-set + recent + token-search contributions.
    let a_bill = &result.layer_scores["src/a.rs"];
    let a_layers: Vec<&'static str> = a_bill.iter().map(|(n, _)| *n).collect();
    assert!(a_layers.contains(&LAYER_WORKING_SET));
    assert!(a_layers.contains(&LAYER_RECENT));
    assert!(a_layers.contains(&LAYER_TOKEN_SEARCH));
}

if stage_a_score > 0.0 {
    trace.push(
        "boost:stage-a",
        (stage_a_score * self.ranking.stage_a_weight).min(self.ranking.stage_a_cap),
    );
    if let Some(file_reasons) = self.preselect.reasons.get(&file_path) {
        for r in file_reasons.iter().take(3) {
            reasons.push(r.clone());
        }
    }
    // Per-layer score bill from preselect: explains how stage-A
    // arrived at this file's score (e.g. `preselect:working-set:+2.00`).
    // Additive on top of the legacy reason strings above; bounded by
    // the number of preselect layers.
    if let Some(bill) = self.preselect.layer_scores.get(&file_path) {
        for (layer, layer_score) in bill {
            reasons.push(format!("preselect:{layer}:+{layer_score:.2}"));
        }
    }
}

//! Fixpoint dirty-closure policy for incremental dirty propagation.
//!
//! Single home for the iteration policy and budget semantics: given the set of
//! files whose export fingerprint changed in the current scan, repeatedly find
//! their importers, promote the promotable ones (Skip → DirtyResolveOnly), and
//! re-check whether each promoted file's *effective* export surface changed
//! (re-export chains) so THEIR importers get promoted too. Iterates until
//! convergence, a global file budget, or a hard round cap.
//!
//! The function is pure with respect to I/O: graph lookups and surface-change
//! checks are injected as closures so the policy is unit-testable without a DB.

pub enum DirtyPropagationStatus {
    /// Fixpoint converged: every transitive importer was promoted (including
    /// the trivial case where no export surface changed).
    Normal,
    /// The closure stopped early — round cap hit, or the global budget was
    /// exceeded after round 1 — but the promotions kept form a valid
    /// complete-round prefix of the full closure.
    PartialClosure,
    /// Round-1 direct importers exceeded the budget; only a bounded prefix
    /// was processed. The replay basis remains durable until completion.
    BudgetExceeded,
    /// Dirty propagation is disabled via config.
    Disabled,
}

// Surface evaluation: this round's promotions plus every previously
// promoted-but-unchanged file, re-checked until no more flips. A file
// promoted alongside a sibling it re-exports from only flips after
// the sibling enters `changed_so_far`, hence the inner fixpoint.
// Flipped files are NOT promoted again — only their importer
// expansion (next round's frontier) was missing.

/// Which of the given promoted (DirtyResolveOnly) files' *effective*
/// export surfaces changed, given the set of files whose exports changed
/// so far (batch hook for `compute_dirty_closure`).
///
/// Promoted files are content-unchanged and reloaded without parsing. Their
/// persisted file-local declaration evidence stays intact. A changed
/// forwarding target can nevertheless affect their importers. Unknown or
/// missing surfaces conservatively continue the existing bounded closure;
/// known surfaces use resolved forwarding routes. No recursive hashes.
///
/// Re-export targets are fetched via one batched
/// `reexport_targets_for_files` query per pass (only for files not yet in
/// `targets_cache`, which memoizes them across rounds and re-evaluation
/// passes), replacing the previous per-file N+1 query.
///
/// P2-A records ES direct/two-step forwarding, static CommonJS bindings,
/// Rust visibility-qualified use and Python imports. It reuses existing
/// resolved import rows; unresolved routes remain a project-model limit.
/// Python star interfaces are explicitly Unknown. Dependency events and
/// durable remainder reuse this finite-set expansion through reconcile.rs.
pub(super) fn promoted_export_surfaces_changed(
    &self,
    files: &[String],
    changed_so_far: &HashSet<String>,
    targets_cache: &mut HashMap<String, Vec<String>>,
) -> CcResult<Vec<String>> {
    let missing: Vec<&str> = files
        .iter()
        .filter(|path| !targets_cache.contains_key(path.as_str()))
        .map(|path| path.as_str())
        .collect();
    if !missing.is_empty() {
        let mut fetched = self.db.reads().reexport_targets_for_files(&missing)?;
        for path in missing {
            // Files with no resolved re-exports are absent from the batch
            // result; cache an empty target list so they are not refetched.
            let targets = fetched.remove(path).unwrap_or_default();
            targets_cache.insert(path.to_string(), targets);
        }
    }
    let surfaces = self.db.reads().public_surfaces(files)?;
    Ok(files
        .iter()
        .filter(|path| {
            if surfaces
                .get(path.as_str())
                .is_none_or(|s| s.fingerprint().is_none() || !s.forwards.is_empty())
            {
                // A facade can acquire a previously missing route. Treat its
                // contribution conservatively as changed even when the old
                // resolved-import table has no route yet. Finite file sets,
                // not recursive hashes, stabilize cycles.
                return true;
            }
            targets_cache
                .get(path.as_str())
                .is_some_and(|targets| targets.iter().any(|t| changed_so_far.contains(t)))
        })
        .cloned()
        .collect())
}

/// Build a `surface_changed_of` hook from a file → re-export targets map:
/// a file's surface changes iff any of its targets is in the
/// changed-so-far set (mirrors the production re-export check).
fn surface_from_reexports(
    targets: HashMap<&'static str, Vec<&'static str>>,
) -> impl FnMut(&[String], &HashSet<String>) -> CcResult<Vec<String>> {
    move |files: &[String], changed: &HashSet<String>| {
        Ok(files
            .iter()
            .filter(|path| {
                targets
                    .get(path.as_str())
                    .is_some_and(|deps| deps.iter().any(|dep| changed.contains(*dep)))
            })
            .cloned()
            .collect())
    }
}

/// Check the stored schema version and apply the full schema if needed.
///
/// Returns `Ok(Initialized)` if the database was freshly created (version was 0).
/// Returns `Ok(UpToDate)` if the version already matches.
/// Returns `Ok(Migrated)` if the stored version was the adjacent additive
/// predecessor — the missing objects were created in place, data preserved.
/// Returns `Ok(Mismatch)` for any other stored version — the caller should
/// destructively reset the database and retry.
pub fn migrate_index_db(conn: &Connection) -> CcResult<SchemaStatus> {
    let stored = conn
        .pragma_query_value(None, "user_version", |row| row.get::<_, u32>(0))
        .map_err(db_err)?;

    if stored == CURRENT_SCHEMA_VERSION {
        crate::read_generation::ensure(conn)?;
        return Ok(SchemaStatus::UpToDate);
    }

    if stored != 0 {
        if stored == ADDITIVE_MIGRATION_FROM {
            // Additive in-place migration: FULL_SCHEMA_SQL is entirely
            // `CREATE ... IF NOT EXISTS`, so re-applying it only creates the
            // objects the stored version lacks. Existing rows, tables and the
            // FTS maintenance model are untouched; the persisted incarnation
            // is deliberately preserved (renewal is reserved for the
            // rebuild/swap protocol).
            tracing::info!(
                from = stored,
                to = CURRENT_SCHEMA_VERSION,
                "applying additive schema migration"
            );
            conn.execute_batch(FULL_SCHEMA_SQL).map_err(|e| {
                cc_model::CcError::Database(format!("additive schema migration failed: {}", e))
            })?;
            conn.pragma_update(None, "user_version", CURRENT_SCHEMA_VERSION)
                .map_err(db_err)?;
            crate::read_generation::ensure(conn)?;
            return Ok(SchemaStatus::Migrated { from: stored });
        }
        tracing::warn!(
            stored_version = stored,
            expected_version = CURRENT_SCHEMA_VERSION,
            "index schema version mismatch, rebuild required"
        );
        return Ok(SchemaStatus::Mismatch { stored });
    }

    // Fresh database (version 0): apply full schema.
    tracing::info!(
        version = CURRENT_SCHEMA_VERSION,
        "initializing index schema"
    );
    conn.execute_batch(FULL_SCHEMA_SQL)
        .map_err(|e| cc_model::CcError::Database(format!("schema init failed: {}", e)))?;
    conn.pragma_update(None, "user_version", CURRENT_SCHEMA_VERSION)
        .map_err(db_err)?;

    crate::read_generation::ensure(conn)?;
    Ok(SchemaStatus::Initialized)
}

